const string W="D:/project/MTGB/design-demos/battlefield-redesign-2026-10-24/";
var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>();var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var results=new System.Collections.Generic.List<object>();int checks=0,failed=0;
void Check(bool pass,string context){checks++;if(!pass)failed++;results.Add(new{pass,context});}
ForgeSeatView Sample()=>JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(W+"native-full-seat.json"));
Transform Root()=>GameObject.Find("Canvas").transform;
Rect Bounds(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c.Min(v=>v.x),c.Min(v=>v.y),c.Max(v=>v.x),c.Max(v=>v.y));}
UnityEngine.EventSystems.PointerEventData Event(Vector2 point)=>new(UnityEngine.EventSystems.EventSystem.current){position=point,pressPosition=point,eligibleForClick=true,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};
GameObject Hit(Vector2 point){var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(Event(point),hits);return hits.FirstOrDefault().gameObject;}
void Expanded(bool value)=>typeof(ForgeBattlefieldController).GetMethod("SetRedesignHandExpanded",flags).Invoke(ui,new object[]{value});
void Quiet(){foreach(var pointer in Root().Find("PlayerHandRoot").GetComponentsInChildren<ForgeBattlefieldCardPointer>()){pointer.ResetHover();pointer.AllowHandHover=false;}typeof(ForgeBattlefieldController).GetMethod("LeaveInspectCard",flags).Invoke(ui,null);}
void Save(string status){var method=Type.GetType("Newtonsoft.Json.JsonConvert, Newtonsoft.Json").GetMethod("SerializeObject",new[]{typeof(object)});System.IO.File.WriteAllText(W+"hand-tray-selection-hover-validation.json",(string)method.Invoke(null,new object[]{new{status,checks,failed,results}}));}
System.Collections.IEnumerator Run(){
 var pick=JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(W+"action-ui-inputs/hand.json"));int calls=0,last=-1;ui.Present(pick,pick.seat,true,i=>{calls++;last=i;},null,"");Expanded(true);yield return new WaitForSecondsRealtime(.35f);
 var hand=Root().Find("PlayerHandRoot");var choice=hand.GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.name.StartsWith("Card_")&&pick.request.options.Any(o=>!o.disabled&&b.name=="Card_"+o.card?.id));int expected=Array.FindIndex(pick.request.options,o=>choice.name=="Card_"+o.card?.id);var pointerChoice=choice.GetComponent<ForgeBattlefieldCardPointer>();pointerChoice.OnPointerEnter(Event(Bounds((RectTransform)choice.transform).center));yield return new WaitForSecondsRealtime(.6f);
 var face=(RectTransform)typeof(ForgeBattlefieldCardPointer).GetField("face",flags).GetValue(pointerChoice);Check(face.GetComponent<Canvas>().overrideSorting&&face.GetComponent<Canvas>().sortingOrder>hand.GetComponent<Canvas>().sortingOrder,"direct selection hover stays above native selection layer");
 var hit=Hit(Bounds(face).center);Check(hit!=null&&hit.GetComponentInParent<UnityEngine.UI.Button>()==choice,"lifted selection face actual raycast");if(hit!=null&&hit.GetComponentInParent<UnityEngine.UI.Button>()==choice){var e=Event(Bounds(face).center);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hit,e,UnityEngine.EventSystems.ExecuteEvents.pointerDownHandler);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hit,e,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);}Check(calls==1&&last==expected,"lifted selection keeps exact native option");Check(choice.gameObject.activeInHierarchy&&face.gameObject.activeInHierarchy,"selection does not hide hand face");pointerChoice.OnPointerExit(Event(Vector2.zero));
 // Separate independent native fixtures, clearing the previous drag's casting preview.
 ui.Present(null,1,false,null,null,"");yield return null;
 var sample=Sample();ui.Present(sample,1,true,_=>{},null,"本地 UI 样本");Expanded(true);foreach(string pool in new[]{"ManaPoolChips","PublicManaPool"})Root().Find(pool).GetComponent<BattlefieldHorizontalScroll>().horizontalNormalizedPosition=0;Quiet();yield return new WaitForSecondsRealtime(.8f);ScreenCapture.CaptureScreenshot(W+"hand-tray-normal.png");yield return new WaitForEndOfFrame();
 Expanded(false);Quiet();yield return new WaitForSecondsRealtime(.4f);ScreenCapture.CaptureScreenshot(W+"hand-tray-lowered.png");yield return new WaitForEndOfFrame();
 // Explicit display adapter: extend the native stack without asserting any new rules outcome.
 var many=Sample();var stack=many.stackItems;many.stackItems=stack.Concat(Enumerable.Range(2,10).Select(i=>{var e=JsonUtility.FromJson<ForgeStackItem>(JsonUtility.ToJson(stack[1]));e.id=99500+i;e.targets=Array.Empty<ForgeStackTarget>();return e;})).ToArray();many.stack=many.stackItems.Select(e=>e.description).ToArray();many.stackCount=12;var own=many.players.First(p=>p.seat==1);var cards=own.hand;own.hand=Enumerable.Range(0,12).Select(i=>{var c=JsonUtility.FromJson<ForgeCardView>(JsonUtility.ToJson(cards[i%cards.Length]));c.id=98500+i;return c;}).ToArray();own.handCount=12;System.IO.File.WriteAllText(W+"hand-hover-over-stack-input.json",JsonUtility.ToJson(many));
 ui.Present(many,1,true,_=>{},null,"本地 UI 样本");Expanded(true);Root().Find("PlayerHandRoot/HandFanNavigation").GetComponent<ForgeHandFanNavigation>().MoveBy(-100000);Quiet();yield return new WaitForSecondsRealtime(.6f);var pointer=Root().Find("PlayerHandRoot").GetComponentsInChildren<ForgeBattlefieldCardPointer>().Where(p=>p.name.StartsWith("Card_")&&p.GetComponent<CanvasGroup>().alpha>.9f).OrderBy(p=>((RectTransform)p.transform).anchoredPosition.x).Last();pointer.AllowHandHover=true;pointer.OnPointerEnter(Event(Bounds((RectTransform)pointer.transform).center));yield return new WaitForSecondsRealtime(.7f);
 face=(RectTransform)typeof(ForgeBattlefieldCardPointer).GetField("face",flags).GetValue(pointer);var a=Bounds(face);var b=Bounds((RectTransform)Root().Find("StackColumn/Viewport"));var overlap=Rect.MinMaxRect(Mathf.Max(a.xMin,b.xMin),Mathf.Max(a.yMin,b.yMin),Mathf.Min(a.xMax,b.xMax),Mathf.Min(a.yMax,b.yMax));Check(overlap.width>1&&overlap.height>1,"capture uses actual hovered-card and stack overlap");if(overlap.width>1&&overlap.height>1){hit=Hit(overlap.center);Check(hit!=null&&hit.GetComponentInParent<ForgeBattlefieldCardPointer>()==pointer,"hover face wins raycast over stack in captured frame");}ScreenCapture.CaptureScreenshot(W+"hand-hover-over-stack.png");yield return new WaitForEndOfFrame();
 pointer.OnPointerExit(Event(Vector2.zero));ui.Present(Sample(),1,false,null,null,"副本 · 只读布局预览");Expanded(true);Save("COMPLETE");
}
System.Collections.IEnumerator Guard(){var it=Run();for(int i=0;i<10000;i++){bool next=false;object value=null;try{next=it.MoveNext();if(next)value=it.Current;}catch(Exception e){failed++;results.Add(new{exception=e.ToString()});Save("ERROR");yield break;}if(!next)break;yield return value;}}
Save("STARTING");ui.StartCoroutine(Guard());return "Native selection hover check and actual Unity captures started";
